```go
package main

import "fmt"

type User struct{ Name string }

func (u User) Greet() string { return "Hello, " + u.Name }

type Admin struct {
    User
    Role string
}

func main() {
    admin := Admin{User: User{Name: "Mina"}, Role: "owner"}
    fmt.Println(admin.Name, admin.Greet())
    fmt.Println(admin.User.Name, admin.Role)
}
```
The short selectors are promoted from the embedded field. `admin.User` remains the explicit contained value.

```go
package main

import "fmt"

type Contact struct{ Name string }
type Company struct{ Name string }

type Profile struct {
    Contact
    Company
}

func main() {
    profile := Profile{
        Contact: Contact{Name: "Mina"},
        Company: Company{Name: "Acme"},
    }
    fmt.Println(profile.Contact.Name, profile.Company.Name)
    // fmt.Println(profile.Name) // ambiguous selector
}
```
Both embedded fields remain accessible. The commented short selector fails because neither depth-one `Name` is preferred.

```go
package main

import "fmt"

type Loader interface{ Load() string }
type Saver interface{ Save(string) }

type Store interface {
    Loader
    Saver
}

type Memory struct{ value string }

func (m *Memory) Load() string       { return m.value }
func (m *Memory) Save(value string)  { m.value = value }

func replace(store Store, value string) string {
    store.Save(value)
    return store.Load()
}

func main() {
    memory := &Memory{}
    fmt.Println(replace(memory, "ready"))
}
```
`*Memory` satisfies the combined `Store` contract because its method set contains both embedded requirements.
